const crypto = require('crypto');
const secret = $env.AED_WEBHOOK_SECRET;
if (!secret) throw new Error('AED_WEBHOOK_SECRET is required');
const body = JSON.stringify($json.body ?? {});
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(body).digest('hex');
const provided = String($json.headers?.['x-aed-signature'] ?? '');
const valid = provided.length === expected.length && crypto.timingSafeEqual(Buffer.from(provided), Buffer.from(expected));
if (!valid) throw new Error('Invalid AED webhook signature');
return [{ json: { accepted: true, correlationId: $json.body.correlationId, idempotencyKey: $json.body.idempotencyKey } }];
